function stop(){sequence++;if(audio){audio.onended=audio.onerror=null;audio.pause();audio=null}if(window.speechSynthesis)window.speechSynthesis.cancel();el('kp183Build').classList.remove('is-speaking-onset','is-speaking-final','is-united');el('kp183Listen').disabled=false}
function audioFallback(item,token){if(token!==sequence)return;var build=el('kp183Build');el('kp183Listen').disabled=false;if(!window.speechSynthesis){el('kp183Status').textContent='音声を再生できません。';return}try{var u=new SpeechSynthesisUtterance(item.tone);u.lang='zh-CN';u.rate=.72;u.onend=function(){if(token!==sequence)return;build.classList.remove('is-speaking-final');build.classList.add('is-united');el('kp183Status').textContent=item.tone+' を聞いてみよう。'};u.onerror=function(){el('kp183Status').textContent='音声を再生できません。';};el('kp183Status').textContent='代替音声で再生中…';window.speechSynthesis.cancel();window.speechSynthesis.speak(u)}catch(e){el('kp183Status').textContent='音声を再生できません。'}}
