function update(){el('kp183Count').textContent=(data.indexOf(selected)+1)+' / '+data.length;el('kp183Onset').textContent=selected.a;el('kp183Final').textContent=selected.f;el('kp183Result').textContent=selected.s;el('kp183Cue').textContent=selected.cue;el('kp183Sound').textContent=selected.tone+' · 第1声';el('kp183ListenLabel').textContent='もう一度 '+selected.tone;el('kp183Hint').textContent='音節全体の '+selected.tone+'を聞いて、'+selected.a+' と '+selected.f+' がどうつながるか見てみよう。'}
