function endRecording(){clearTimeout(recordTimer);if(recorder&&recorder.state==='recording')recorder.stop()}
el('kp183Record').addEventListener('click',function(){var button=el('kp183Record');if(recorder&&recorder.state==='recording'){endRecording();return}if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia||!window.MediaRecorder){el('kp183RecordStatus').textContent='このブラウザでは録音できません。';return}stop();button.disabled=true;el('kp183RecordStatus').textContent='マイクの使用を確認しています…';var request=window.KP134&&window.KP134.microphone?window.KP134.microphone():navigator.mediaDevices.getUserMedia({audio:true});request.then(function(s){stream=s;var types=['audio/mp4','audio/webm;codecs=opus','audio/webm'];var mime=types.find(function(t){return MediaRecorder.isTypeSupported&&MediaRecorder.isTypeSupported(t)});recorder=mime?new MediaRecorder(stream,{mimeType:mime}):new MediaRecorder(stream);var chunks=[];recorder.ondataavailable=function(e){if(e.data&&e.data.size)chunks.push(e.data)};recorder.onstop=function(){if(stream){if(window.KP134&&window.KP134.releaseMicrophone)window.KP134.releaseMicrophone(stream);else stream.getTracks().forEach(function(t){t.stop()});stream=null}button.disabled=false;button.textContent='● もう一度録音';var blob=new Blob(chunks,{type:recorder.mimeType||'audio/webm'});if(recordedUrl)URL.revokeObjectURL(recordedUrl);recordedUrl=URL.createObjectURL(blob);recordedAudio=new Audio(recordedUrl);el('kp183Replay').disabled=!blob.size;if(closing){closing=false;chunks.length=0;return}el('kp183RecordStatus').textContent=blob.size?'録音できたよ。自分の音を聞いてみよう。':'録音を保存できませんでした。もう一度試してね。'};recorder.onerror=function(){el('kp183RecordStatus').textContent='録音中に問題が起きました。もう一度試してね。';button.disabled=false};recorder.start();button.disabled=false;button.textContent='■ 録音を止める';el('kp183RecordStatus').textContent='録音中だよ。読み終えたら停止してね（最大5秒）。';clearTimeout(recordTimer);recordTimer=setTimeout(endRecording,5000)}).catch(function(){button.disabled=false;el('kp183RecordStatus').textContent='マイクを使えません。サイトの設定を確認してね。'})});
