function startQuiz(){el('kp183Groups').querySelectorAll('button').forEach(function(b){b.disabled=true});el('kp183Stations').querySelectorAll('button').forEach(function(b){b.disabled=true});qOrder=groups.find(function(x){return x.id===group}).keys.slice().sort(function(){return Math.random()-.5}).slice(0,Math.min(3,groups.find(function(x){return x.id===group}).keys.length));qIndex=0;score=0;done=false;el('kp183Check').hidden=true;el('kp183Quiz').hidden=false;ask()}
